#include <iostream>
#include <csignal>
#include <atomic>
#include <mutex>
#include <thread>
#include <vector>
#include <unordered_map>
#include <cstring>
#include <functional>

namespace blockchain {

struct Transaction {
    uint64_t sender;
    uint64_t receiver;
    uint64_t amount;
    uint64_t nonce;
};

class CircuitBreaker {
private:
    volatile sig_atomic_t tripped_;
    volatile sig_atomic_t failure_count_;
    volatile sig_atomic_t threshold_;
    volatile sig_atomic_t state_; // 0=closed, 1=open, 2=half-open

    // Recovery bookkeeping
    volatile sig_atomic_t pending_recovery_;
    uint64_t recovery_balance_;
    uint64_t recovery_target_;

public:
    CircuitBreaker() : tripped_(0), failure_count_(0), threshold_(3),
                       state_(0), pending_recovery_(0),
                       recovery_balance_(0), recovery_target_(0) {}

    void set_threshold(int t) { threshold_ = t; }
    int get_state() const { return state_; }
    bool is_tripped() const { return tripped_ != 0; }

    void record_failure() {
        failure_count_++;
        if (failure_count_ >= threshold_) {
            trip();
        }
    }

    void trip() {
        tripped_ = 1;
        state_ = 1; // open
        pending_recovery_ = 1;
    }

    void begin_recovery(uint64_t balance, uint64_t target) {
        recovery_balance_ = balance;
        recovery_target_ = target;
    }

    bool finalize_recovery() {
        if (pending_recovery_) {
            // Signal-safe check: only recover if balance meets target
            if (recovery_balance_ >= recovery_target_) {
                state_ = 2; // half-open
                pending_recovery_ = 0;
                return true;
            }
        }
        return false;
    }

    void reset() {
        failure_count_ = 0;
        tripped_ = 0;
        state_ = 0;
        pending_recovery_ = 0;
        recovery_balance_ = 0;
        recovery_target_ = 0;
    }
};

class SmartContract {
private:
    std::unordered_map<uint64_t, uint64_t> balances_;
    std::mutex state_mutex_;
    CircuitBreaker breaker_;
    std::vector<Transaction> pending_queue_;
    volatile sig_atomic_t processing_;

    static SmartContract* instance_;

    // Internal transfer - assumes lock is held
    bool do_transfer(const Transaction& tx) {
        if (balances_[tx.sender] < tx.amount) {
            breaker_.record_failure();
            return false;
        }
        balances_[tx.sender] -= tx.amount;
        balances_[tx.receiver] += tx.amount;
        return true;
    }

public:
    SmartContract() : processing_(0) {
        instance_ = this;
    }

    static SmartContract* get_instance() { return instance_; }

    void initialize(uint64_t addr, uint64_t balance) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        balances_[addr] = balance;
    }

    uint64_t get_balance(uint64_t addr) {
        std::lock_guard<std::mutex> lock(state_mutex_);
        return balances_[addr];
    }

    bool submit_transaction(const Transaction& tx) {
        std::lock_guard<std::mutex> lock(state_mutex_);

        if (breaker_.get_state() == 1) {
            // Circuit is open - queue for later
            pending_queue_.push_back(tx);
            return false;
        }

        processing_ = 1;
        bool result = do_transfer(tx);
        processing_ = 0;
        return result;
    }

    // Called from signal handler context to attempt emergency recovery
    static void signal_recovery_handler(int sig) {
        SmartContract* self = instance_;
        if (!self) return;

        if (self->breaker_.is_tripped()) {
            // Read balance for recovery check - NOT signal safe!
            // This accesses std::unordered_map from signal context
            uint64_t contract_balance = 0;
            for (auto& pair : self->balances_) {
                contract_balance += pair.second;
            }

            self->breaker_.begin_recovery(contract_balance, 1000);

            if (self->breaker_.finalize_recovery()) {
                // Drain pending queue from signal handler
                // Race: processing_ may be set, and we modify shared state
                self->processing_ = 1;
                for (size_t i = 0; i < self->pending_queue_.size(); i++) {
                    self->do_transfer(self->pending_queue_[i]);
                }
                self->pending_queue_.clear();
                self->processing_ = 0;
                self->breaker_.reset();
            }
        }
    }

    void install_recovery_handler() {
        struct sigaction sa;
        memset(&sa, 0, sizeof(sa));
        sa.sa_handler = signal_recovery_handler;
        sigemptyset(&sa.sa_mask);
        // SA_RESTART allows interrupted syscalls to restart
        sa.sa_flags = SA_RESTART;
        sigaction(SIGUSR1, &sa, nullptr);
    }

    void trigger_recovery() {
        raise(SIGUSR1);
    }

    size_t pending_count() {
        std::lock_guard<std::mutex> lock(state_mutex_);
        return pending_queue_.size();
    }
};

SmartContract* SmartContract::instance_ = nullptr;

} // namespace blockchain

int main() {
    blockchain::SmartContract contract;
    contract.install_recovery_handler();

    contract.initialize(1, 10000);
    contract.initialize(2, 5000);
    contract.initialize(3, 0);

    // Normal operations
    blockchain::Transaction tx1{1, 3, 500, 1};
    contract.submit_transaction(tx1);

    // Force circuit breaker trip
    for (int i = 0; i < 5; i++) {
        blockchain::Transaction bad_tx{3, 1, 99999, (uint64_t)i};
        contract.submit_transaction(bad_tx);
    }

    // This should be queued
    blockchain::Transaction tx2{1, 2, 200, 2};
    contract.submit_transaction(tx2);

    std::cout << "Pending: " << contract.pending_count() << std::endl;
    std::cout << "Balance[1]: " << contract.get_balance(1) << std::endl;

    // Trigger recovery from signal handler - race condition!
    // Another thread could be in submit_transaction when signal fires
    std::thread worker([&]() {
        for (int i = 0; i < 100; i++) {
            blockchain::Transaction tx{1, 2, 1, (uint64_t)(100+i)};
            contract.submit_transaction(tx);
        }
    });

    // Signal fires while worker may hold mutex or be mid-transfer
    std::this_thread::sleep_for(std::chrono::milliseconds(1));
    contract.trigger_recovery();

    worker.join();

    std::cout << "Final Balance[1]: " << contract.get_balance(1) << std::endl;
    std::cout << "Final Balance[2]: " << contract.get_balance(2) << std::endl;
    return 0;
}
